/**
 * Hand-translation rule artifacts (paper §12.3 realcorpus).
 *
 * One annotated graph constructor per source path — reviewable JSON manifests
 * under test/fixtures/vercel-corpus/realcorpus/, generated by the mechanical
 * procedure described in the paper (site extraction + demand inference).
 *
 * Load order:
 *   1. realcorpus/<relative>.json if present (artifact)
 *   2. else live extractGraphsFromSource (regenerate path)
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, statSync } from 'node:fs'
import { join, relative, dirname } from 'node:path'
import { extractGraphsFromSource } from './ast-extract.ts'
import { graphToManifest, manifestToGraph, type GraphManifest } from './extract.ts'
import type { StepGraph } from '../types.ts'

export interface RealCorpusEntry {
  /** Path relative to vercel-corpus root, e.g. cookbook/saga.ts */
  sourcePath: string
  workflowName: string
  /** Paper mechanical translation notes */
  translationNotes: string[]
  graph: StepGraph
  /** Absolute path to JSON artifact if loaded from disk */
  artifactPath?: string
}

export interface RealCorpusArtifact {
  sourcePath: string
  workflowName: string
  paperCommit: string
  translationNotes: string[]
  graph: GraphManifest
}

const TRANSLATION_NOTES = [
  'use step call → step site (module-qualified optional)',
  'sleep() → timer site',
  'createWebhook/createHook + await → hook site',
  'Promise.all → join-observed parallel group (source branch order is identity)',
  'Promise.race/any → race group (no independent pairs)',
  'if/else on step results → branch predicates when present',
  'demand fields via access-path inference on consumer slices (TS AST preferred)',
]

/**
 * Generate realcorpus JSON artifacts for all .ts under corpusRoot.
 */
export function generateRealCorpusArtifacts (
  corpusRoot: string,
  opts: { paperCommit?: string, outDir?: string } = {}
): RealCorpusArtifact[] {
  const outDir = opts.outDir ?? join(corpusRoot, 'realcorpus')
  const paperCommit = opts.paperCommit ?? readCommit(corpusRoot)
  const artifacts: RealCorpusArtifact[] = []

  for (const abs of walkTs(corpusRoot)) {
    if (abs.includes('/realcorpus/')) continue
    const rel = relative(corpusRoot, abs).replace(/\\/g, '/')
    let src: string
    try {
      src = readFileSync(abs, 'utf8')
    } catch {
      continue
    }
    const { workflows, warnings } = extractGraphsFromSource(src, {
      modulePath: rel,
      qualifiedNames: false,
    })
    for (const w of workflows) {
      if (w.graph.sites.length === 0 && warnings.length) continue
      const art: RealCorpusArtifact = {
        sourcePath: rel,
        workflowName: w.name,
        paperCommit,
        translationNotes: [...TRANSLATION_NOTES, ...warnings.map(x => `warn: ${x}`)],
        graph: graphToManifest(w.graph),
      }
      artifacts.push(art)
      const outPath = join(outDir, rel.replace(/\.ts$/, '') + `__${w.name}.json`)
      mkdirSync(dirname(outPath), { recursive: true })
      writeFileSync(outPath, JSON.stringify(art, null, 2) + '\n')
    }
  }
  return artifacts
}

/**
 * Load all realcorpus artifacts from disk.
 */
export function loadRealCorpusArtifacts (corpusRoot: string): RealCorpusEntry[] {
  const dir = join(corpusRoot, 'realcorpus')
  if (!existsSync(dir)) return []
  const entries: RealCorpusEntry[] = []
  for (const abs of walkJson(dir)) {
    try {
      const raw = JSON.parse(readFileSync(abs, 'utf8')) as RealCorpusArtifact
      entries.push({
        sourcePath: raw.sourcePath,
        workflowName: raw.workflowName,
        translationNotes: raw.translationNotes ?? TRANSLATION_NOTES,
        graph: manifestToGraph(raw.graph),
        artifactPath: abs,
      })
    } catch {
      // skip bad artifact
    }
  }
  return entries
}

function readCommit (corpusRoot: string): string {
  try {
    return readFileSync(join(corpusRoot, 'SOURCE_COMMIT'), 'utf8').trim()
  } catch {
    return 'unknown'
  }
}

function walkTs (dir: string): string[] {
  const out: string[] = []
  let names: string[]
  try {
    names = readdirSync(dir)
  } catch {
    return out
  }
  for (const n of names) {
    const p = join(dir, n)
    try {
      const st = statSync(p)
      if (st.isDirectory()) {
        if (n === 'realcorpus' || n === 'node_modules') continue
        out.push(...walkTs(p))
      } else if (n.endsWith('.ts') && !n.endsWith('.d.ts')) {
        out.push(p)
      }
    } catch {
      // skip
    }
  }
  return out
}

function walkJson (dir: string): string[] {
  const out: string[] = []
  let names: string[]
  try {
    names = readdirSync(dir)
  } catch {
    return out
  }
  for (const n of names) {
    const p = join(dir, n)
    try {
      const st = statSync(p)
      if (st.isDirectory()) out.push(...walkJson(p))
      else if (n.endsWith('.json')) out.push(p)
    } catch {
      // skip
    }
  }
  return out
}
